function getComments(content, bid, cid) {
  const { source, java, cache } = this;
  try {
    let separator = "\n";
    if (/<p>/.test(content)) {
      content = content.replace("<p>","").replace("\n", "");
      separator = "<p>";
    } else {
      content = content.replace(/\r/g, "").replace(/\n$/, "");
    }
    let comcont = content.split(separator);
    let comments = java.ajax(`https://m.qidian.com/majax/chapterReview/reviewSummary?bookId=${bid}&chapterId=${cid}&_csrfToken=${this.generateCsrfToken()},{"headers":{"Cookie":"${this.qdtoken()}"}}`);
    let commentList = [];
    if (comments) {
      try {
        let commentData = JSON.parse(comments);
        commentList = commentData?.data?.list || [];
      } catch (e) {}
    }
